<script setup lang="ts">
import { computed, onMounted, ref } from 'vue';
import { api, items } from '../api';
import { filePayload, pathId, safeJson } from './common';
const busy=ref(false), error=ref(''), notice=ref('');
const instanceId=ref('');
const system=ref<'openclaw'|'hermes'>('openclaw'), source=ref<'zip'|'directory'>('zip'), directory=ref(''), workspace=ref(''), file=ref<File>();
const batches=ref<any[]>([]), selected=ref<any>(), plan=ref<any>(), compatibility=ref<any>(), history=ref<any[]>([]), archive=ref<any>(), search=ref(''), name=ref(''), messageLimit=ref(10), password=ref(''), confirmed=ref(false);
const choices=ref<Record<string,{strategy:string;content?:unknown}>>({}), merges=ref<Record<string,string>>({});
const reviewItem=ref<any>(), draft=ref<any>(), reviewed=ref<any>(), memoryScope=ref('owner'), memoryContent=ref(''), requiredTools=ref(''), toolsConfirmed=ref(false), toolMap=ref('{}'), mapping=ref('{}');
const createdObjects=computed(()=>{if(selected.value?.state!=='COMPLETED')return [];const ids=new Set((selected.value.created??[]).filter((x:any)=>!x.kind||x.kind==='migration_objects').map((x:any)=>x.id));return (selected.value.plan?.items??[]).filter((x:any)=>ids.has(x.targetId));});
const groups=computed(()=>{const result:Record<string,any[]>={}; for(const item of plan.value?.items ?? []) (result[item.type ?? '其他'] ??= []).push(item); return result;});
const key=(item:any)=>`${item.type}\0${item.sourceId}`;
const objectContent=(item:any)=>item.status==='conflict' && item.choice?.strategy==='manualmerge'?item.choice.content:item.content;
async function run(fn:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';notice.value='';try{await fn();}catch(e){error.value=e instanceof Error?e.message:'请求失败';}finally{busy.value=false;}}
async function refresh(){batches.value=items(await api('migrations'));}
async function select(id:string){selected.value=await api('migrations/'+pathId(id));plan.value=selected.value?.plan;choices.value={};confirmed.value=false;reviewItem.value=undefined;draft.value=undefined;reviewed.value=undefined;}
async function create(){await run(async()=>{if(!instanceId.value.trim())throw new Error('请输入稳定的来源实例标识');const input:any={system:system.value,instanceId:instanceId.value.trim()};if(source.value==='zip'){if(!file.value)throw new Error('请选择 ZIP 文件');const data=await filePayload(file.value);input.archiveBase64=data.base64;input.sha256=data.sha256;}else{if(!directory.value.trim())throw new Error('请输入只读来源目录');input.directory=directory.value.trim();if(workspace.value.trim())input.workspace=workspace.value.trim();}const result=await api('migrations','POST',input);await refresh();await select(result.id);notice.value='扫描完成，请检查服务端报告。';});}
async function makePlan(){await run(async()=>{const selectedChoices:Record<string,unknown>={};for(const [id,choice] of Object.entries(choices.value)){if(choice.strategy==='manualmerge'){try{selectedChoices[id]={strategy:choice.strategy,content:JSON.parse(merges.value[id] ?? '')};}catch{throw new Error('手动合并内容必须是有效 JSON');}}else selectedChoices[id]=choice;}plan.value=await api(`migrations/${pathId(selected.value.id)}/plan`,'POST',{choices:selectedChoices});confirmed.value=false;notice.value='计划已更新，请重新检查并确认。';});}
async function execute(action:'apply'|'rollback'){await run(async()=>{if(!password.value||!confirmed.value)throw new Error('请输入密码并确认操作');if(action==='apply'&&!plan.value?.hash)throw new Error('请先生成计划');const body=action==='apply'?{planHash:plan.value.hash,password:password.value,confirm:true}:{password:password.value,confirm:true};try{const result=await api(`migrations/${pathId(selected.value.id)}/${action}`,'POST',body);selected.value={...selected.value,result};await refresh();await select(selected.value.id);notice.value=action==='apply'?'服务端已返回执行结果，请检查批次状态。':'服务端已返回回滚结果，请检查冲突。';if(action==='rollback') selected.value={...selected.value,rollbackReport:result};}finally{password.value='';confirmed.value=false;}});}
function parseObject(value:string){const parsed=JSON.parse(value);if(!parsed || typeof parsed!=='object' || Array.isArray(parsed))throw new Error('请输入 JSON 对象');return parsed;}
function reviewOptions(){return {toolMap:parseObject(toolMap.value),...(toolsConfirmed.value?{requiredTools:requiredTools.value.split(/[,\n]/).map(x=>x.trim()).filter(Boolean)}:{})};}
async function chooseReview(item:any){reviewItem.value=item;draft.value=undefined;reviewed.value=undefined;memoryScope.value='owner';const content=objectContent(item);memoryContent.value=typeof content==='string'?content:safeJson(content);requiredTools.value='';toolsConfirmed.value=false;toolMap.value='{}';mapping.value='{}';if(['cron','skill'].includes(item.type))await loadDraft();}
async function loadDraft(){const options=reviewOptions();draft.value=await api(`migrations/objects/${pathId(reviewItem.value.targetId)}/draft`,'POST',options);mapping.value=JSON.stringify(draft.value.draft??{},null,2);}
async function approveMemory(){await run(async()=>{await api(`migrations/objects/${pathId(reviewItem.value.targetId)}/memory`,'POST',{approved:true,scope:memoryScope.value,content:memoryContent.value});notice.value='Memory 已审查并保存。';});}
async function approveNative(){await run(async()=>{const options=reviewOptions();const fresh=await api(`migrations/objects/${pathId(reviewItem.value.targetId)}/draft`,'POST',options);draft.value=fresh;if(fresh.type==='skill' && fresh.missing?.length)throw new Error('请先解决缺失项：'+fresh.missing.join(', '));const value=parseObject(mapping.value);delete value.enabled;delete value.requiredTools;delete value.toolMap;reviewed.value=await api(`migrations/objects/${pathId(reviewItem.value.targetId)}/review`,'POST',{approved:true,mapping:value,...options});if(reviewed.value?.enabled!==false)throw new Error('服务端未确认创建为停用状态');notice.value='已审查并创建停用对象；激活需要再次确认。';});}
async function activateNative(){await run(async()=>{if(!reviewed.value || reviewed.value.enabled!==false)throw new Error('请先审查并创建停用对象');const result=await api(`migrations/objects/${pathId(reviewItem.value.targetId)}/activate`,'POST',{confirm:true});reviewed.value=result;notice.value='服务端已处理激活请求，请检查结果。';});}
async function loadHistory(){history.value=items(await api('migrations/history?search='+encodeURIComponent(search.value)));}
async function continuation(){await run(async()=>{const result=await api(`migrations/history/${pathId(archive.value.id)}/continue`,'POST',{...(name.value?{name:name.value}:{}),messageLimit:Number(messageLimit.value)});notice.value=`已创建新会话：${result?.id ?? result?.conversation?.id ?? '请在对话中查看'}`;});}
onMounted(()=>run(async()=>{const results=await Promise.allSettled([refresh(),api('migrations/compatibility').then(v=>compatibility.value=v),loadHistory()]);const failures=results.filter(r=>r.status==='rejected') as PromiseRejectedResult[];if(failures.length)throw failures[0].reason;}));
</script>
<template>
<div :aria-busy="busy"><p v-if="busy" role="status">正在处理…</p><p v-if="error" role="alert">{{ error }}</p><p v-if="notice" role="status">{{ notice }}</p>
<section><h3>来源与扫描</h3><p>只读取静态备份或受限只读目录。来源脚本不会在此运行；账号需要重新授权。</p>
<label>来源实例标识<input v-model="instanceId" placeholder="同一旧实例每次导入使用相同标识"></label><label>来源系统<select v-model="system"><option value="openclaw">OpenClaw</option><option value="hermes">Hermes</option></select></label>
<label>来源类型<select v-model="source"><option value="zip">ZIP 备份</option><option value="directory">只读目录</option></select></label>
<label v-if="source==='zip'">ZIP 文件<input type="file" accept=".zip,application/zip" @change="file=($event.target as HTMLInputElement).files?.[0]"></label>
<template v-else><label>只读来源目录<input v-model="directory" placeholder="已配置的只读根目录内路径"></label><label>工作区目录（可选）<input v-model="workspace"></label></template>
<button :disabled="busy" @click="create">扫描来源</button></section>
<section><h3>批次与预览</h3><button :disabled="busy" @click="run(refresh)">刷新批次</button><ul><li v-for="batch in batches" :key="batch.id"><button :disabled="busy" @click="run(()=>select(batch.id))">{{ batch.id }} · {{ batch.state ?? batch.status }}</button></li></ul>
<template v-if="selected"><h4>批次详情</h4><pre>{{ safeJson(selected) }}</pre><button :disabled="busy" @click="makePlan">生成或更新计划</button>
<template v-if="plan"><p>计划哈希：{{ plan.hash }}</p><section v-for="(group,type) in groups" :key="type"><h4>{{ type }}（{{ group.length }}）</h4><article v-for="item in group" :key="key(item)"><pre>{{ safeJson(item) }}</pre><template v-if="item.status==='conflict'"><label>冲突处理<select v-model="(choices[key(item)] ??= {strategy:'keep'}).strategy"><option value="keep">保留现有</option><option value="new">新增副本</option><option value="manualmerge">手动合并</option></select></label><label v-if="choices[key(item)]?.strategy==='manualmerge'">合并内容（JSON）<textarea v-model="merges[key(item)]"></textarea></label></template></article></section><details><summary>完整计划</summary><pre>{{ safeJson(plan) }}</pre></details></template>
<label>管理员密码<input v-model="password" type="password" autocomplete="current-password"></label><label><input v-model="confirmed" type="checkbox">我已检查计划或回滚影响，并确认操作</label><button :disabled="busy || !plan?.hash || !confirmed" @click="execute('apply')">按此哈希执行迁移</button><button :disabled="busy || !confirmed" @click="execute('rollback')">回滚此批次</button></template></section>
<section v-if="selected"><h3>已导入对象审查</h3><p>仅显示本批创建的对象。来源内容不可信，审查不会执行来源脚本。</p><table><thead><tr><th>类型</th><th>来源 ID</th><th>目标 ID</th><th>操作</th></tr></thead><tbody><tr v-for="item in createdObjects" :key="item.targetId"><td>{{ item.type }}</td><td>{{ item.sourceId }}</td><td>{{ item.targetId }}</td><td><button v-if="['memory','instruction','cron','skill'].includes(item.type)" :disabled="busy" @click="run(()=>chooseReview(item))">审查对象</button></td></tr></tbody></table><template v-if="reviewItem"><h4>审查 {{ reviewItem.type }} · {{ reviewItem.sourceId }}</h4><pre>{{ safeJson(objectContent(reviewItem)) }}</pre><template v-if="['memory','instruction'].includes(reviewItem.type)"><label>Memory 范围<input v-model="memoryScope"></label><label>审查后内容<textarea v-model="memoryContent"></textarea></label><button :disabled="busy" @click="approveMemory">批准并保存 Memory</button></template><template v-else><p>填写必需工具和映射后重新获取草稿。所有依赖必须映射到已注册工具。</p><label>必需工具（逗号或换行分隔）<textarea v-model="requiredTools"></textarea></label><label><input v-model="toolsConfirmed" type="checkbox">已审查必需工具列表（空列表表示无依赖）</label><label>工具映射（JSON 对象）<textarea v-model="toolMap"></textarea></label><button :disabled="busy" @click="run(loadDraft)">检查草稿依赖</button><pre v-if="draft">{{ safeJson(draft) }}</pre><label>审查映射（JSON 对象）<textarea v-model="mapping"></textarea></label><p>定时任务使用 schedules 字段；Skill 使用 name、description、content。审查后对象默认停用。</p><button :disabled="busy || !draft || (draft.type==='skill' && draft.missing?.length)" @click="approveNative">批准并创建停用对象</button><pre v-if="reviewed">{{ safeJson(reviewed) }}</pre><button :disabled="busy || !reviewed || reviewed.enabled!==false" @click="activateNative">确认激活已审查对象</button></template></template></section>
<section><h3>历史归档</h3><label>搜索历史<input v-model="search"></label><button :disabled="busy" @click="run(loadHistory)">查询历史</button><ul><li v-for="entry in history" :key="entry.id"><button :disabled="busy" @click="run(async()=>archive=await api('migrations/history/'+pathId(entry.id)))">{{ entry.sourceId ?? entry.id }}</button></li></ul><template v-if="archive"><p>原始历史只读；继续时会创建新会话，历史内容是不可信背景。</p><pre>{{ safeJson(archive) }}</pre><label>新会话名称<input v-model="name"></label><label>最近消息数量<input v-model.number="messageLimit" type="number" min="0" max="50"></label><button :disabled="busy" @click="continuation">从历史创建新会话</button></template></section>
<section><h3>来源版本兼容性</h3><p>未知版本未经过验证。</p><pre v-if="compatibility">{{ safeJson(compatibility) }}</pre></section></div>
</template>
